UPDATE knowledge_document_task SET status='SUCCEEDED', finished_at=#{now}, heartbeat_at=#{now},
    worker_id=NULL, run_token=NULL, last_error=NULL
WHERE id=#{id} AND status='RUNNING' AND run_token=#{runToken}

UPDATE knowledge_document_task SET status='FAILED', finished_at=#{now}, heartbeat_at=#{now},
    worker_id=NULL, run_token=NULL, last_error=#{error}
WHERE id=#{id} AND status='RUNNING' AND run_token=#{runToken}
